#!/usr/bin/env python3
from binascii import hexlify, unhexlify
import binascii
import sys

def load_ciphertext(filename):
    with open(filename, 'r') as f:
        hex_data = f.read().strip().replace('\n', '')
    return unhexlify(hex_data)

def to_num(s):
    x = 0
    for i in range(len(s)):
        x += s[-1-i] * pow(256, i)
    return x

def get_nums(s, n):
    sections = [s[i:i+n] for i in range(0, len(s), n)]
    if len(sections[-1]) < n:
        sections[-1] = sections[-1] + (b"\x00" * (n - len(sections[-1])))
    return [to_num(x) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    x = val_list[0]
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    result = bytearray()
    for i in range(n):
        result.append(x % 256)
        x //= 256
    result.reverse()
    return bytes(result)

def decr_vals(c_chr, k_chr, n):
    mask = (1 << n) - 1
    result = (c_chr - k_chr) & mask
    return result

def decrypt(k, c, n):
    if n >= 8:
        raise ValueError("n is too high!")

    # Convert key to bytes if it's a string
    if isinstance(k, str):
        k = k.encode()

    # Repeat key to match ciphertext length
    rep_k = k * (len(c) // len(k)) + k[:len(c) % len(k)]

    # Get value lists for ciphertext and key
    c_val_list = [get_vals(x, n) for x in get_nums(c, n)]
    k_val_list = [get_vals(x, n) for x in get_nums(rep_k, n)]

    # Flatten lists
    c_vals, k_vals = [], []
    for lst in c_val_list:
        c_vals += lst
    for lst in k_val_list:
        k_vals += lst

    # Decrypt values
    m_vals = [decr_vals(c_vals[i], k_vals[i % len(k_vals)], n)
            for i in range(len(c_vals))]

    # Group values and convert to characters
    m_val_list = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]
    return b''.join([get_chrs(lst, n) for lst in m_val_list])

def hexdump(data):
    length = 16
    result = []
    for i in range(0, len(data), length):
        chunk = data[i:i+length]
        hex_line = ' '.join(f'{b:02x}' for b in chunk)
        ascii_line = ''.join(chr(b) if 32 <= b <= 126 else '.' for b in chunk)
        result.append(f'{i:08x}  {hex_line:<{length*3}}  |{ascii_line}|')
    return '\n'.join(result)

def test_decrypt():
    ciphertext = load_ciphertext('ciphertext')
    test_key = b'test'

    print(f"Testing with key: {test_key}\n")

    for n in range(1, 8):
        print(f"Testing with n = {n}")
        try:
            result = decrypt(test_key, ciphertext, n)
            print("Hex dump of result:")
            print(hexdump(result))
            print()
        except Exception as e:
            print(f"Error: {e}\n")

if __name__ == "__main__":
    test_decrypt()

