from pwn import *
import string

def to_num(s):
    x = 0
    for i in range(len(s)): x += ord(s[-1-i]) * pow(256, i)
    return x

def get_nums(s, n):
    sections = [s[i:i+n] for i in range(0, len(s), n)]
    sections[-1] = sections[-1] + ("\x00" * (n - len(sections[-1])))
    return [to_num(x) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    x = val_list[0]
    chrs = []
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    for i in range(n):
        chrs.append(chr(x % 256))
        x //= 256
    chrs.reverse()
    return "".join(chrs)

def decr_vals(c_val, k_val, n):
    mask = (1 << n) - 1
    return (c_val - k_val) & mask

def decrypt(k, c, n):
    if (n >= 8): raise ValueError("n is too high!")
    rep_k = k * (len(c) // len(k)) + k[:len(c) % len(k)]
    c_val_list = [get_vals(x, n) for x in get_nums(c, n)]
    k_val_list = [get_vals(x, n) for x in get_nums(rep_k, n)]
    c_vals, k_vals, m_vals = [], [], []
    for lst in c_val_list: c_vals += lst
    for lst in k_val_list: k_vals += lst
    m_vals = [decr_vals(c_vals[i], k_vals[i % len(k_vals)], n)
        for i in range(0, len(c_vals))]
    m_val_list = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]
    return "".join([get_chrs(lst, n) for lst in m_val_list])

def has_flag_pattern(text):
    return 'flag{' in text or 'FLAG{' in text

def try_decrypt_with_key(ciphertext, key, n):
    try:
        decrypted = decrypt(key, ciphertext, n)
        if all(c in string.printable for c in decrypted):
            return decrypted
    except:
        pass
    return None

def analyze_key_length(ciphertext, max_length=16):
    results = []
    # Convert hex string to bytes
    cipher_bytes = bytes.fromhex(ciphertext.replace('\n', ''))

    for length in range(1, max_length + 1):
        # Split ciphertext into blocks of key length
        blocks = [cipher_bytes[i:i+length] for i in range(0, len(cipher_bytes), length)]
        # Count matching bytes at same positions
        matches = 0
        for i in range(len(blocks)-1):
            for j in range(len(blocks[i])):
                if j < len(blocks[i+1]) and blocks[i][j] == blocks[i+1][j]:
                    matches += 1
        results.append((length, matches))

    # Sort by number of matches, descending
    return sorted(results, key=lambda x: x[1], reverse=True)

def brute_force_key_start(ciphertext, key_length, n):
    flag_start = 'flag{'
    promising_keys = []

    # Convert ciphertext from hex
    cipher_bytes = bytes.fromhex(ciphertext.replace('\n', ''))

    # Try all printable characters for the first key_length positions
    for c in string.printable:
        key_start = c * key_length
        try:
            decrypted = decrypt(key_start, cipher_bytes.decode('latin1'), n)
            if decrypted.startswith(flag_start):
                promising_keys.append(key_start)
        except:
            continue

    return promising_keys

def main():
    with open('ciphertext', 'r') as f:
        ciphertext = f.read()

    print("[*] Analyzing possible key lengths...")
    key_lengths = analyze_key_length(ciphertext)
    print(f"Most promising key lengths: {key_lengths[:5]}")

    print("\n[*] Trying decryption with different n values...")
    for key_length, score in key_lengths[:5]:
        print(f"\nTesting key length: {key_length}")
        for n in range(1, 8):
            print(f"Testing n={n}")
            keys = brute_force_key_start(ciphertext, key_length, n)
            for key in keys:
                try:
                    decrypted = decrypt(key, bytes.fromhex(ciphertext.replace('\n', '')).decode('latin1'), n)
                    if has_flag_pattern(decrypted):
                        print(f"[+] Potential flag found with n={n}, key_length={key_length}:")
                        print(f"Key start: {key[:16]}")
                        print(f"Decrypted: {decrypted[:50]}...")
                except:
                    continue

if __name__ == '__main__':
    main()

