    chrs.reverse()
    return bytes(chrs)

def decrypt_block(c_val, k_val, n):
    mask = (1 << n) - 1
    return (c_val - k_val) & mask

def process_key(key, n):
    k_nums = get_nums(key, n)
    k_vals = []
    for k_num in k_nums:
        k_vals.extend(get_vals(k_num, n))
    return k_vals

def process_ciphertext(ciphertext, n):
    c_nums = get_nums(ciphertext, n)
    c_vals = []
    for c_num in c_nums:
        c_vals.extend(get_vals(c_num, n))
    return c_vals

def decrypt(ciphertext, key, n):
    try:
        k_vals = process_key(key, n)
        c_vals = process_ciphertext(ciphertext, n)

        m_vals = []
        for i in range(len(c_vals)):
            m_val = decrypt_block(c_vals[i], k_vals[i % len(k_vals)], n)
            m_vals.append(m_val)

        m_chunks = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]
        result = b''
        for chunk in m_chunks:
            if len(chunk) == 8:
                result += get_chrs(chunk, n)
        return result
    except Exception as e:
        return None

def try_detect_key_length(ciphertext):
    # Try to detect patterns in the ciphertext that might indicate key length
    coincidences = []
    for keylen in range(1, 9):
        count = 0
        for i in range(len(ciphertext) - keylen):
            if ciphertext[i] == ciphertext[i + keylen]:
                count += 1
        coincidences.append((keylen, count))
    return sorted(coincidences, key=lambda x: x[1], reverse=True)

def main():
    # Read hex ciphertext
    with open('ciphertext', 'rb') as f:
        hex_data = f.read().strip()
    # Convert hex string to bytes, removing newlines
    hex_str = hex_data.decode().replace('\n', '')
    ciphertext = bytes.fromhex(hex_str)

    print("[*] Starting optimized decryption")
    print(f"[+] Ciphertext length: {len(ciphertext)} bytes")

