    key_lengths = try_detect_key_length(ciphertext)
    print("[+] Potential key lengths (ordered by likelihood):")
    for kl, score in key_lengths:
        print(f"    Length {kl}: score {score}")

    # Common characters that might appear in keys
    common_chars = (string.ascii_letters + string.digits + '_{}').encode()

    # Try different n values (2-7 as per challenge constraints)
    for n in range(2, 8):
        print(f"\n[+] Testing with n={n}")

        # Try key lengths in order of likelihood
        for key_len, _ in key_lengths:
            print(f"  [*] Testing key length: {key_len}")

            # First try common characters that might appear in flags
            for key_chars in itertools.product(common_chars, repeat=key_len):
