                decrypted = decrypt(ciphertext, key, n)

                if decrypted and b'flag{' in decrypted:
                    flag_start = decrypted.index(b'flag{')
                    flag_end = decrypted.find(b'}', flag_start)
                    if flag_end != -1 and flag_end - flag_start < 100:
                        potential_flag = decrypted[flag_start:flag_end+1]
                        if all(32 <= c <= 126 for c in potential_flag):
                            print(f"\n[!] Potential flag found!")
                            print(f"    n = {n}")
                            print(f"    key = {key}")
                            print(f"    flag = {potential_flag.decode()}")
                            if len(potential_flag) > 6:  # More than just 'flag{}'
                                # Found a promising result, focus on this n and key length
                                return

if __name__ == '__main__':
    main()

