    if len(sections[-1]) < n:
        sections[-1] = sections[-1] + b'\x00' * (n - len(sections[-1]))
    return [to_num(x) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    x = val_list[0]
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    chrs = []
    for i in range(n):
        chrs.append(x % 256)
        x //= 256
    chrs.reverse()
    return bytes(chrs)

def decrypt_vals(c_val, k_val, n):
    mask = (1 << n) - 1
    m_val = (c_val - k_val) & mask
    return m_val

def decrypt(ciphertext, key, n):
    try:
        rep_k = key * (len(ciphertext) // len(key)) + key[:len(ciphertext) % len(key)]
        c_val_list = [get_vals(x, n) for x in get_nums(ciphertext, n)]
        k_val_list = [get_vals(x, n) for x in get_nums(rep_k, n)]

        c_vals = []
        k_vals = []
        for lst in c_val_list: c_vals += lst
        for lst in k_val_list: k_vals += lst

        m_vals = [decrypt_vals(c_vals[i], k_vals[i % len(k_vals)], n)
                for i in range(len(c_vals))]

        m_val_list = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]
        return b''.join([get_chrs(lst, n) for lst in m_val_list if len(lst) == 8])
    except:
        return None

